// Input must come from trusted Instagram bridge with Header Auth.
const inbound=$input.first()?.json||{};
const b=inbound.body||inbound;
const out=[];
// Authenticated event-driven timer callbacks: never register as user messages.
if(b.event_type==='timer_check' && ['nudge','close'].includes(b.timer_action)){
 const id=String(b.ig_user_id||'');
 const last=Number(b.expected_last_inbound_at);
 if(/^\d{5,40}$/.test(id)&&Number.isFinite(last)&&last>0&&/^ig_\d+_\d{1,6}$/.test(String(b.session_id||''))){
  return [{json:{event_type:'timer_check',ig_user_id:id,session_id:String(b.session_id),timer_action:String(b.timer_action),expected_last_inbound_at:last}}];
 }
 return [];
}

function str(v,max=900){return String(v??'').slice(0,max);}
function add(e){
  if(!['dm','comment'].includes(e.event_type)||!e.event_id)return;
  if(e.is_echo===true||e.from_own_account===true)return;
  if(e.event_type==='dm'&&!/^\d{5,40}$/.test(String(e.ig_user_id||'')))return;
  if(e.event_type==='comment'&&!/^\d{5,80}$/.test(String(e.comment_id||'')))return;
  out.push({json:{event_type:e.event_type,event_id:str(e.event_id,160),ig_user_id:str(e.ig_user_id,40),username:str(e.username,100),name:str(e.name,100),text:str(e.text||e.message?.text,900),quick_reply_payload:str(e.quick_reply_payload||e.postback_payload||e.message?.quick_reply?.payload||e.quick_reply?.payload||e.payload,150),comment_id:str(e.comment_id,80),media_id:str(e.media_id,80),reel_url:str(e.reel_url,450),timestamp:e.timestamp||new Date().toISOString(),channel:'instagram',source:'Instagram'}});
}
if(['dm','comment'].includes(b.event_type))add(b);
for(const entry of Array.isArray(b.entry)?b.entry:[]){
  for(const m of Array.isArray(entry.messaging)?entry.messaging:[]){
    if(m.message?.is_echo===true)continue;
    const id=m.sender?.id,mid=m.message?.mid||m.postback?.mid;
    if(!id||id===entry.id||!mid)continue;
    add({event_type:'dm',event_id:mid,ig_user_id:id,text:m.message?.text||m.postback?.title||'',quick_reply_payload:m.message?.quick_reply?.payload||m.postback?.payload||'',timestamp:m.timestamp||entry.time});
  }
  for(const c of Array.isArray(entry.changes)?entry.changes:[]){
    if(!['comments','live_comments'].includes(c.field))continue;
    const v=c.value||{};if(!v.id&&!v.comment_id)continue;
    if(String(v.from?.id||v.user_id||'')===String(entry.id||'')||v.from_own_account===true)continue;
    add({event_type:'comment',event_id:'comment:'+(v.id||v.comment_id),ig_user_id:v.from?.id||v.user_id||'',username:v.from?.username||v.username||'',comment_id:v.id||v.comment_id,media_id:v.media?.id||v.media_id||'',reel_url:v.media?.permalink||'',text:v.text||'',timestamp:v.timestamp||entry.time});
  }
}
return out;

// TBW Instagram DM Reply Logic — clean WhatsApp button, no long URL in chat.
// Replace only the code in the "IG - DM Reply Logic" node.
// CATS, SVCS, M must be supplied by the preceding "IG - Language + Catalog" node.

const ev = $input.first()?.json || {};
if (ev.event_type !== 'dm' || ev.accepted !== true || ev.reply_allowed !== true || ev.mode !== 'ai') return [];

const id = String(ev.ig_user_id || '');
if (!/^\d{5,40}$/.test(id)) return [];

const { CATS, SVCS, M } = ev.ig_catalog || {};
if (!CATS || !SVCS || !M) throw new Error('Missing Instagram catalog from IG - Language + Catalog');

const mem = $getWorkflowStaticData('global');
mem.tbwIgSessions ??= {};
mem.tbwIgLeadCooldowns ??= {};

const now = Date.now();
const sessions = mem.tbwIgSessions;
let s = sessions[id];
const isNew = !s || s.closed || now - Number(s.lastInboundAt || 0) >= 20 * 60000;
if (isNew) {
  s = {
    sessionId: 'ig_' + now + '_' + id.slice(-6),
    stage: 'new',
    language: '',
    category: '',
    service: '',
    lastInboundAt: 0,
    updatedAt: now,
    promptAt: 0,
    nudged: false,
    closed: false,
    alertedServices: {},
    lastFallbackAt: 0,
  };
  sessions[id] = s;
}
s.lastInboundAt = now;
s.updatedAt = now;
s.nudged = false;

const raw = String(ev.text || '').trim().slice(0, 900);
const normalized = raw.toLocaleLowerCase().replace(/\s+/g, ' ').trim();
const click = String(ev.quick_reply_payload || '').trim();
const language = () => s.language || 'en';
const translations = () => M[language()] || M.en;
const quick = (title, payload) => ({ content_type: 'text', title: String(title).slice(0, 20), payload });
const waBase = 'https://wa.me/917972020292';

function waLink() {
  const category = s.category ? (CATS[s.category]?.en || '') : '';
  const text = [
    'Hello The Business Work!',
    'I came from Instagram.',
    category ? 'Category: ' + category : '',
    s.service ? 'Service: ' + s.service : '',
    'I want more details and would like to book an appointment.',
  ].filter(Boolean).join('\n');
  return waBase + '?text=' + encodeURIComponent(text);
}

function textReply(text, options = []) {
  return {
    recipient: { id },
    message: {
      text: String(text).slice(0, 950),
      ...(options.length ? { quick_replies: options.slice(0, 13) } : {}),
    },
  };
}

// IMPORTANT: Link exists ONLY on the WhatsApp button, not in the message text.
function urlReply(text) {
  const t = translations();
  return {
    recipient: { id },
    message: {
      attachment: {
        type: 'template',
        payload: {
          template_type: 'button',
          text: String(text).slice(0, 640),
          buttons: [
            { type: 'web_url', url: waLink(), title: 'Chat on WhatsApp' },
            { type: 'postback', title: String(t.menu || 'Main Menu').slice(0, 20), payload: 'IG_MENU' },
            { type: 'postback', title: String(t.endbtn || 'End Chat').slice(0, 20), payload: 'IG_END' },
          ],
        },
      },
    },
  };
}

function answer(payload, newLead = false) {
  s.promptAt = 0;
  return [{
    json: {
      event_type: 'dm_reply',
      ig_user_id: id,
      username: ev.username || '',
      source_event_id: ev.event_id,
      session_id: s.sessionId,
      category: s.category,
      service: s.service,
      language: language(),
      new_lead: newLead,
      igPayload: payload,
    },
  }];
}

function langMenu() {
  s.stage = 'language';
  s.language = '';
  s.lastFallbackAt = 0;
  return answer(textReply(
    M.en.hello + '\n\n1. English  2. हिंदी\n3. Hinglish  4. मराठी\n(Type 1–4 on desktop)',
    [quick('English', 'IG_LANG_en'), quick('हिंदी', 'IG_LANG_hi'), quick('Hinglish', 'IG_LANG_hinglish'), quick('मराठी', 'IG_LANG_mr')]
  ));
}

function catMenu() {
  const t = translations();
  s.stage = 'category';
  s.lastFallbackAt = 0;
  const keys = ['ai', 'crm', 'workflow', 'social'];
  const names = keys.map((key, i) => `${i + 1}. ${CATS[key][language()]}`).join('\n');
  return answer(textReply(
    `${t.category}\n\n${names}\n\n(Type 1–4 on desktop)`,
    keys.map((key, i) => quick(`${i + 1}. ${CATS[key][language()].slice(0, 16)}`, 'IG_CAT_' + key))
      .concat([quick(t.endbtn, 'IG_END')])
  ));
}

function svcMenu(cat) {
  const t = translations();
  s.stage = 'service';
  s.category = cat;
  s.lastFallbackAt = 0;
  const list = SVCS[cat] || [];
  const names = list.map((svc, i) => `${i + 1}. ${svc[language()]}`).join('\n');
  return answer(textReply(
    `${t.service}\n\n${names}\n\n(Type 1–6 on desktop)`,
    list.map((svc, i) => quick(`${i + 1}. ${svc[language()].slice(0, 16)}`, `IG_SVC_${cat}_${i}`))
      .concat([quick(t.back, 'IG_MENU'), quick(t.endbtn, 'IG_END')])
  ));
}

function inferLanguage() {
  if (/^IG_LANG_(en|hi|hinglish|mr)$/.test(click)) return click.slice(8);
  const options = {
    english: 'en', en: 'en', '1': 'en',
    hindi: 'hi', 'हिंदी': 'hi', 'हिन्दी': 'hi', hi: 'hi', '2': 'hi',
    hinglish: 'hinglish', '3': 'hinglish',
    marathi: 'mr', 'मराठी': 'mr', mr: 'mr', '4': 'mr',
  };
  return options[normalized] || '';
}

function indexFromText(max) {
  const match = normalized.match(/^([1-9])(?:\s*[.):-]|\s*$)/);
  const i = match ? Number(match[1]) - 1 : -1;
  return i >= 0 && i < max ? i : -1;
}

function inferCategory() {
  if (click.startsWith('IG_CAT_') && CATS[click.slice(7)]) return click.slice(7);
  const keys = ['ai', 'crm', 'workflow', 'social'];
  const i = indexFromText(4);
  if (i >= 0) return keys[i];
  for (const key of keys) {
    const names = Object.values(CATS[key]).map(value => String(value).toLocaleLowerCase());
    if (names.includes(normalized) || normalized.startsWith(key + ' ') || normalized === key) return key;
  }
  return '';
}

function inferService() {
  const match = /^IG_SVC_(ai|crm|workflow|social)_(\d)$/.exec(click);
  if (match && SVCS[match[1]]?.[Number(match[2])]) return [match[1], Number(match[2])];
  if (s.stage !== 'service' || !s.category) return null;
  const list = SVCS[s.category] || [];
  const i = indexFromText(list.length);
  if (i >= 0) return [s.category, i];
  for (let j = 0; j < list.length; j++) {
    const names = Object.values(list[j]).map(value => String(value).toLocaleLowerCase());
    if (names.includes(normalized) || names.some(value => normalized === value.slice(0, 17))) return [s.category, j];
  }
  return null;
}

function navInput() {
  if (click === 'IG_END' || ['end', 'end chat', 'stop', 'bye', 'chat band', 'चैट बंद', 'चॅट बंद'].includes(normalized)) return 'end';
  if (click === 'IG_MENU' || ['menu', 'main menu', 'back', 'पीछे', 'मुख्य मेनू', 'मागे'].includes(normalized)) return 'menu';
  if (click === 'IG_RESUME' || ['continue', 'yes continue', 'yes, continue', 'हाँ, जारी रखें', 'हो, पुढे चला'].includes(normalized)) return 'resume';
  if (['whatsapp', 'chat on whatsapp', 'appointment', 'book appointment', 'book consultation', 'more details'].includes(normalized)) return 'whatsapp';
  return '';
}

if (s.stage === 'new') return langMenu();

const nav = navInput();
if (nav === 'end') {
  s.closed = true;
  s.stage = 'ended';
  s.promptAt = 0;
  return answer(textReply(translations().end));
}

if (s.stage === 'language') {
  const chosen = inferLanguage();
  if (chosen) {
    s.language = chosen;
    s.lastFallbackAt = 0;
    return catMenu();
  }
  if (s.lastFallbackAt && now - s.lastFallbackAt < 120000) return [];
  s.lastFallbackAt = now;
  return answer(textReply(
    'Please select a language by tapping or typing 1–4. 😊\n1. English  2. हिंदी  3. Hinglish  4. मराठी',
    [quick('English', 'IG_LANG_en'), quick('हिंदी', 'IG_LANG_hi'), quick('Hinglish', 'IG_LANG_hinglish'), quick('मराठी', 'IG_LANG_mr')]
  ));
}

if (!s.language) return langMenu();
if (nav === 'menu') return catMenu();
if (nav === 'resume') return s.stage === 'service' && s.category ? svcMenu(s.category) : catMenu();
if (nav === 'whatsapp') return answer(urlReply(translations().fallback));

const cat = inferCategory();
if (cat && (s.stage === 'category' || click.startsWith('IG_CAT_'))) return svcMenu(cat);

const svc = inferService();
if (svc) {
  s.category = svc[0];
  s.service = SVCS[svc[0]][svc[1]].en;
  s.stage = 'selected';
  s.lastFallbackAt = 0;
  const leadKey = id + '|' + s.category + '|' + s.service;
  const lastLead = Number(mem.tbwIgLeadCooldowns[leadKey] || 0);
  const newLead = !(lastLead && now - lastLead < 86400000);
  const serviceTitle = SVCS[svc[0]][svc[1]][language()];
  return answer(urlReply(translations().selected.replace('{service}', serviceTitle)), newLead);
}

if (raw || click) {
  if (s.lastFallbackAt && now - s.lastFallbackAt < 120000) return [];
  s.lastFallbackAt = now;
  // Keep existing stage: after fallback, typed category/service must still work.
  return answer(urlReply(translations().fallback));
}

return [];

