// One easy-to-edit test switch. TEST MODE is OFF by default to prevent unsolicited replies.
// To test WITHOUT dashboard, set enabled=true and enter EXACT Instagram Reel media ID.
// After testing: enabled=false and use dashboard automation rules.
const TEST_RULE={
 enabled:false,
 media_id:'',
 trigger:'any', // 'any' or 'keywords'
 keywords:['interested','demo'],
 private_reply_text:'Thanks for commenting! 👋 Reply Hi to explore our services.',
 public_reply_enabled:true,
 public_reply_text:'Thanks for your comment! 😊'
};
const e=$input.first()?.json||{};
const exactId=String(e.media_id||'');
let matched=TEST_RULE.enabled&&/^\d{5,80}$/.test(String(TEST_RULE.media_id))&&exactId===String(TEST_RULE.media_id);
if(matched&&TEST_RULE.trigger==='keywords'){
 const words=(TEST_RULE.keywords||[]).map(x=>String(x).toLowerCase()).filter(Boolean);
 const comment=String(e.text||'').toLowerCase();
 matched=words.some(word=>comment.includes(word));
}
if(matched){
 return [{json:{...e,rule_source:'local_test',approved:true,reply_text:TEST_RULE.private_reply_text,
 public_reply_enabled:TEST_RULE.public_reply_enabled,public_reply_text:TEST_RULE.public_reply_text,
 rule_id:'local-test-'+exactId}}];
}
// Important: if test rule is enabled but comment does not match, do not fall through to dashboard.
if(TEST_RULE.enabled)return [];
return [{json:{...e,rule_source:'dashboard'}}];

// Normalize the dashboard /comment-check response or local test rule into one safe shape.
// Public reply ALWAYS requires an explicit true flag in the dashboard response.
const result=$input.first()?.json||{};
const incoming=$('IG - Deduplicate via Bridge').first().json||{};
const r=result.rule||result.data?.rule||result.data||result;
const approved=r.approved===true;
const media=String(r.media_id||r.ig_media_id||r.reel_media_id||'');
if(media && media!==String(incoming.media_id||''))return [];
const privateText=String(r.reply_text||r.initial_private_reply_message||r.private_reply_text||'').trim().slice(0,950);
const publicEnabled=[r.public_reply_enabled,r.auto_reply_to_comments,r.autoReplyToComments,r.public_comment_reply_enabled,r.auto_reply_public].some(x=>x===true);
const publicText=String(r.public_reply_text||r.public_comment_reply_text||r.auto_reply_comment_text||'Thanks for your comment! 😊').trim().slice(0,400);
return [{json:{...incoming,rule_id:String(r.rule_id||r.id||''),approved,
 reply_text:privateText,public_reply_enabled:publicEnabled,public_reply_text:publicText,
 rule_source:r.rule_source||'dashboard'}}];

const r=$input.first()?.json||{};
if(!r.approved||r.public_reply_enabled!==true||!r.public_reply_text||!/^[0-9]{5,80}$/.test(String(r.comment_id||'')))return [];
// Only reply to fresh verified Instagram comments. Never post to somebody else's Reel.
const v=r.timestamp;
const n=typeof v==='number'?v:Number(v);
const ts=Number.isFinite(n)&&n>1000000000? (n<1e12?n*1000:n) : Date.parse(String(v||''));
if(!Number.isFinite(ts)||Date.now()-ts>=7*86400000||ts>Date.now()+300000)return [];
return [{json:{comment_id:String(r.comment_id),media_id:String(r.media_id||''),rule_id:r.rule_id||'',source_event_id:r.event_id,
 public_reply_text:String(r.public_reply_text).trim().slice(0,400)}}];

const sent=$input.first()?.json||{};
const src=$('IG - Prepare Public Comment Reply').first().json;
return [{json:{channel:'instagram',event_type:'public_comment_reply',source_event_id:src.source_event_id,
comment_id:src.comment_id,media_id:src.media_id,rule_id:src.rule_id,
accepted_by_provider:!!sent.id&&!sent.error,provider_comment_id:sent.id||'',error:sent.error||null}}];

